package com.therighthon.rnr.common.recipe;
import com.therighthon.rnr.RoadsAndRoofs; import net.minecraft.world.item.crafting.RecipeSerializer; import net.minecraftforge.registries.DeferredRegister; import net.minecraftforge.registries.ForgeRegistries; import net.minecraftforge.registries.RegistryObject;
public final class RNRRecipeSerializers { public static final DeferredRegister<RecipeSerializer<?>> RECIPE_SERIALIZERS=DeferredRegister.create(ForgeRegistries.RECIPE_SERIALIZERS,RoadsAndRoofs.MOD_ID); public static final RegistryObject<RNRDamageInputsShapelessRecipe.Serializer> DAMAGE_INPUTS_SHAPELESS=RECIPE_SERIALIZERS.register("damage_inputs_shapeless_crafting",RNRDamageInputsShapelessRecipe.Serializer::new); public static final RegistryObject<MattockRecipe.Serializer> MATTOCK_RECIPE=RECIPE_SERIALIZERS.register("mattock",MattockRecipe.Serializer::new); public static final RegistryObject<BlockModRecipe.Serializer> BLOCK_MOD_RECIPE=RECIPE_SERIALIZERS.register("block_mod",BlockModRecipe.Serializer::new); private RNRRecipeSerializers(){} }
